'use strict';
const $ = s => document.querySelector(s);
const colors = {Banque:'#245c4e',Immobilier:'#87ab96',Crypto:'#d9b97c',Autre:'#b5c8d4',Dette:'#bd8178'};
const banks = ['BoursoBank','Banque Populaire du Sud'];
const providers = [...banks,'Bricks','La Première Brique','Bitstack'];
const money = n => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n);
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const escape = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s&&s<=today();}
function legacyDate(s){if(validDate(s))return s;const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s||'');return m&&validDate(`${m[3]}-${m[2]}-${m[1]}`)?`${m[3]}-${m[2]}-${m[1]}`:'';}
function totals(list){const gross=list.filter(a=>a.category!=='Dette').reduce((s,a)=>s+a.amount,0);const debt=list.filter(a=>a.category==='Dette').reduce((s,a)=>s+a.amount,0);return {gross,debt,total:gross-debt};}
function normalizeAsset(a){if(!a||typeof a.provider!=='string'||!a.provider.trim()||typeof a.name!=='string'||!a.name.trim()||!Object.hasOwn(colors,a.category)||!Number.isFinite(a.amount)||a.amount<0||a.amount>1e14)throw Error('Un actif contient un nom, une catégorie ou un montant invalide.');if(a.valuationDate&&!validDate(a.valuationDate))throw Error('Date de valorisation invalide ou future.');return {id:typeof a.id==='string'?a.id:crypto.randomUUID(),provider:a.provider.trim().slice(0,80),name:a.name.trim().slice(0,100),category:a.category,amount:a.amount,valuationDate:a.valuationDate||legacyDate(a.date),notes:typeof a.notes==='string'?a.notes.slice(0,300):''};}
function normalizeHistory(rows){if(!Array.isArray(rows))throw Error('Historique invalide.');const map=new Map();for(const h of rows){if(!h||!validDate(h.date)||!Number.isFinite(h.total))throw Error('Historique invalide.');const gross=h.gross??h.total,debt=h.debt??0;if(!Number.isFinite(gross)||!Number.isFinite(debt)||gross<0||debt<0||Math.abs(gross-debt-h.total)>.02)throw Error('Totaux historiques incohérents.');map.set(h.date,{date:h.date,total:h.total,gross,debt});}return [...map.values()].sort((a,b)=>a.date.localeCompare(b.date));}
let assets=[],history=[],demo=true,filter='all',editing=null,loadError=false;
try {const raw=localStorage.getItem('horizon-v2');if(raw){const d=JSON.parse(raw);if(d.version!==2||!Array.isArray(d.assets))throw Error();assets=d.assets.map(normalizeAsset);history=normalizeHistory(d.history);demo=false;}else {const old=localStorage.getItem('horizon-v1');if(old){const d=JSON.parse(old);if(!Array.isArray(d))throw Error();assets=d.map(normalizeAsset);history=normalizeHistory(JSON.parse(localStorage.getItem('horizon-history-v1')||'[]'));demo=false;}}}catch {loadError=true;}
if(demo)assets=[{provider:'BoursoBank',name:'Compte courant & Livret A',category:'Banque',amount:42500},{provider:'Bricks',name:'Portefeuille immobilier',category:'Immobilier',amount:18200},{provider:'La Première Brique',name:'Projets participatifs',category:'Immobilier',amount:12500},{provider:'Bitstack',name:'Épargne Bitcoin',category:'Crypto',amount:8800},{provider:'Bourse',name:'Plan d’épargne en actions',category:'Autre',amount:24500}].map(a=>({...a,id:crypto.randomUUID(),valuationDate:today(),notes:''}));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000);}
function commit(nextAssets,nextHistory=history,{snapshot=true}={}){try{const next=nextAssets.map(normalizeAsset);let h=normalizeHistory(nextHistory);if(snapshot){h=h.filter(x=>x.date!==today());h.push({date:today(),...totals(next)});h.sort((a,b)=>a.date.localeCompare(b.date));}localStorage.setItem('horizon-v2',JSON.stringify({version:2,assets:next,history:h}));assets=next;history=h;demo=false;loadError=false;render();return true;}catch(err){toast(err instanceof SyntaxError?'Données invalides.':err.message||'Enregistrement impossible.');return false;}}
function formatDate(date){return date?new Date(date+'T12:00:00').toLocaleDateString('fr-FR'):'Date à préciser';}
function age(date){return date?Math.floor((new Date(today()+'T12:00:00Z')-new Date(date+'T12:00:00Z'))/86400000):Infinity;}
function render(){const t=totals(assets);$('#total').textContent=money(t.total);$('#invested').textContent=money(t.gross);$('#debt').textContent=money(t.debt);$('#count').textContent=String(new Set(assets.map(a=>a.provider)).size).padStart(2,'0');$('#assetCount').textContent=' · '+assets.length;$('#mode').textContent=demo?'Mode démonstration':'Suivi manuel';$('#modeText').textContent=loadError?'Données locales illisibles : elles sont conservées. Restaurez une sauvegarde avant de les remplacer.':demo?'Montants fictifs. Ajoutez un actif pour démarrer votre portefeuille.':'Valeurs saisies ou importées, sans synchronisation automatique.';$('#clear').textContent=demo?'Commencer avec mes données':'Effacer mes données';const stale=assets.filter(a=>age(a.valuationDate)>30);$('#freshness').textContent=demo?'Exemple de portefeuille — aucune donnée réelle.':!assets.length?'Ajoutez votre premier compte ou placement pour commencer.':stale.length?`${stale.length} élément(s) à actualiser : valeur de plus de 30 jours ou date non renseignée.`:'Toutes les valeurs sont datées des 30 derniers jours.';
const cats=Object.keys(colors).filter(c=>c!=='Dette'&&assets.some(a=>a.category===c&&a.amount>0));$('#allocationCount').textContent=cats.length;let pos=0;$('#donut').style.background=t.gross?'conic-gradient('+cats.map(c=>{const start=pos;pos+=assets.filter(a=>a.category===c).reduce((s,a)=>s+a.amount,0)/t.gross*100;return `${colors[c]} ${start}% ${pos}%`;}).join(',')+')':'#edf0f2';$('#legend').innerHTML=cats.map(c=>`<div><span class="dot" style="background:${colors[c]}"></span>${c} <strong>${Math.round(assets.filter(a=>a.category===c).reduce((s,a)=>s+a.amount,0)/(t.gross||1)*100)} %</strong></div>`).join('');
const list=assets.filter(a=>filter==='all'||a.category===filter);$('#empty').classList.toggle('hide',list.length>0);$('#rows').innerHTML=list.map(a=>`<tr><td><div class="provider"><span class="icon">${escape(a.provider[0])}</span><span><strong>${escape(a.provider)}</strong><br><span class="muted">${escape(a.name)}</span>${a.notes?`<br><span class="muted">${escape(a.notes)}</span>`:''}</span></div></td><td><span class="pill">${escape(a.category)}</span></td><td><strong style="color:${a.category==='Dette'?'#a85f55':'inherit'}">${a.category==='Dette'?'− ':''}${money(a.amount)}</strong></td><td class="muted">${demo?'Exemple':formatDate(a.valuationDate)}${!demo&&age(a.valuationDate)>30?'<br><span style="color:#a7763b">À actualiser</span>':''}</td><td><button class="btn" data-edit="${escape(a.id)}" aria-label="Modifier ${escape(a.name)}">✎</button> <button class="btn" data-delete="${escape(a.id)}" aria-label="Supprimer ${escape(a.name)}">×</button></td></tr>`).join('');
$('#sources').innerHTML=providers.map(p=>`<div class="row" style="padding:20px 0;border-top:1px solid #edf0f2"><div><strong>${p}</strong><p class="muted" style="margin:5px 0">${banks.includes(p)?'Compte courant, livret ou emprunt : une ligne par compte.':p==='Bitstack'?'Saisissez la valeur actuelle de votre épargne Bitcoin en euros.':'Une ligne par projet : capital restant investi et liquidités séparées.'}</p></div><button class="btn" data-source="${p}">Ajouter</button></div>`).join('');renderHistory();}
function renderHistory(){document.querySelector('.periods').classList.add('hide');const show=!demo&&history.length>1;$('#graph').classList.toggle('hide',!show);$('#chartNote').textContent=demo?'L’historique commencera avec vos propres enregistrements.':!show?'L’évolution apparaîtra après des enregistrements sur au moins deux jours.':'Patrimoine net enregistré par jour · les versements et retraits font aussi varier le total.';if(!show)return;$('#graph').style.opacity='1';const lo=Math.min(...history.map(h=>h.total)),hi=Math.max(...history.map(h=>h.total));const first=new Date(history[0].date+'T12:00:00Z').getTime(),last=new Date(history.at(-1).date+'T12:00:00Z').getTime();const path=history.map((h,i)=>`${i?'L':'M'}${(new Date(h.date+'T12:00:00Z').getTime()-first)/(last-first)*650} ${hi===lo?90:165-(h.total-lo)/(hi-lo)*145}`).join(' ');$('#graph svg').innerHTML=`<path d="${path} L650 180H0Z" fill="#e7f1eb"/><path d="${path}" fill="none" stroke="#39745f" stroke-width="2.5"/>`;$('#axis').innerHTML=`<span>${formatDate(history[0].date)}</span><span>${formatDate(history.at(-1).date)}</span>`;}
$('#add').onclick=()=>{editing=null;$('#form').reset();$('#valuationDate').value=today();$('#valuationDate').max=today();$('#modalTitle').textContent='Ajouter un actif ou une dette';$('#modal').showModal();};$('#close').onclick=()=>$('#modal').close();
$('#form').onsubmit=e=>{e.preventDefault();const amount=$('#amount').value.trim();if(!amount||!validDate($('#valuationDate').value)){toast('Renseignez un montant et une date valide, au plus tard aujourd’hui.');return;}const a={id:editing||crypto.randomUUID(),provider:$('#provider').value,name:$('#name').value,category:$('#category').value,amount:Number(amount),valuationDate:$('#valuationDate').value,notes:$('#notes').value};const list=demo?[]:assets;if(commit(editing?list.map(x=>x.id===editing?a:x):[...list,a])){$('#modal').close();toast('Valeur enregistrée');}};
$('#rows').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(demo){toast('Ajoutez vos données ou commencez avec un portefeuille vide.');return;}if(b.dataset.delete){if(confirm('Supprimer cet élément ?'))commit(assets.filter(a=>a.id!==b.dataset.delete));}else if(b.dataset.edit){const a=assets.find(a=>a.id===b.dataset.edit);if(!a)return;$('#add').click();editing=a.id;for(const k of ['provider','name','category','amount','valuationDate','notes'])$('#'+k).value=a[k];$('#modalTitle').textContent='Mettre à jour la valeur';}};
$('#sources').onclick=e=>{const b=e.target.closest('[data-source]');if(!b)return;$('#add').click();$('#provider').value=b.dataset.source;$('#category').value=banks.includes(b.dataset.source)?'Banque':b.dataset.source==='Bitstack'?'Crypto':'Immobilier';};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render();});
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x===b));$('#overview').classList.toggle('hide',b.dataset.nav!=='overview');$('#connections').classList.toggle('hide',b.dataset.nav!=='connections');$('#assets').classList.toggle('hide',b.dataset.nav==='connections');$('#pageTitle').textContent={overview:'Votre patrimoine, en clair.',assets:'Tous vos actifs et dettes.',connections:'Vos établissements.'}[b.dataset.nav];});
$('#clear').onclick=()=>{if(confirm('Effacer les actifs et leur historique dans ce navigateur ? Pensez à sauvegarder.')){if(commit([],[])){try{localStorage.removeItem('horizon-v1');localStorage.removeItem('horizon-history-v1');}catch{}toast('Portefeuille remis à zéro');}}};
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#backup').onclick=()=>{if(demo){toast('Ajoutez vos données avant de sauvegarder.');return;}download('horizon-sauvegarde-'+today()+'.json',JSON.stringify({version:2,assets,history},null,2),'application/json');};
$('#restore').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error('Fichier trop volumineux (maximum 5 Mo).');const d=JSON.parse(await f.text());if(![1,2].includes(d.version)||!Array.isArray(d.assets))throw Error('Sauvegarde Horizon invalide.');const next=d.assets.map(a=>({...normalizeAsset(a),id:crypto.randomUUID()})),h=normalizeHistory(d.history);if(confirm(`Restaurer ${next.length} élément(s) et remplacer les données actuelles ?`)){if(commit(next,h,{snapshot:false}))toast('Sauvegarde et historique restaurés');}}catch(err){toast(err.message);}e.target.value='';};
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===';'&&!quoted){row.push(cell);cell='';}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Guillemets non fermés.');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}return rows;}
$('#exportBtn').onclick=()=>{const quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"';const csv='etablissement;nom;categorie;valeur;date;note\n'+assets.map(a=>[a.provider,a.name,a.category,a.amount,a.valuationDate,a.notes].map(quote).join(';')).join('\n');download('horizon-patrimoine.csv','\uFEFF'+csv,'text/csv;charset=utf-8');};
$('#template').onclick=()=>download('modele-horizon.csv','\uFEFFetablissement;nom;categorie;valeur;date;note\n'+providers.map(p=>`${p};À compléter;${banks.includes(p)?'Banque':p==='Bitstack'?'Crypto':'Immobilier'};0;${today()};`).join('\n'),'text/csv;charset=utf-8');
$('#importBtn').onclick=()=>{toast('CSV : etablissement;nom;categorie;valeur;date;note (date ISO). Les anciens CSV à 4 colonnes restent acceptés.');$('#file').click();};
$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error('Fichier trop volumineux (maximum 5 Mo).');const rows=parseCSV((await f.text()).replace(/^\uFEFF/,''));const header=rows.shift()?.map(s=>s.trim().toLowerCase()).join(';');const columns=header==='etablissement;nom;categorie;valeur'?4:header==='etablissement;nom;categorie;valeur;date;note'?6:0;if(!columns)throw Error('En-tête invalide : utilisez le modèle CSV Horizon.');const imported=rows.filter(r=>r.some(c=>c.trim())).map((r,i)=>{if(r.length!==columns||!r[3].trim())throw Error(`Ligne ${i+2} : nombre de colonnes ou montant invalide.`);if(columns===6&&r[4]&&!validDate(r[4]))throw Error(`Ligne ${i+2} : date invalide.`);return normalizeAsset({provider:r[0],name:r[1],category:r[2].trim(),amount:Number(r[3].replace(/\s/g,'').replace(',','.')),valuationDate:columns===6?r[4]:'',notes:columns===6?r[5]:''});});if(!imported.length)throw Error('Aucun élément à importer.');const current=demo?[]:assets;const signature=a=>JSON.stringify([a.provider.toLowerCase(),a.name.toLowerCase(),a.category,a.amount,a.valuationDate]);const keys=new Set(current.map(signature));const unique=imported.filter(a=>{const k=signature(a);if(keys.has(k))return false;keys.add(k);return true;});if(!unique.length)throw Error('Ces lignes existent déjà : aucun doublon ajouté.');if(confirm(`Ajouter ${unique.length} élément(s) ? ${imported.length-unique.length} doublon(s) ignoré(s).`)){if(commit([...current,...unique]))toast(`${unique.length} élément(s) importé(s)`);}}catch(err){toast(err.message);}e.target.value='';};
render();
